import gzip, numpy as np, sys, collections
COMP=str.maketrans('ACGTN','TGCAN')
def rc(s): return s.translate(COMP)[::-1]
P5='TCTTGTGGAAAGGACGAAACACCG'
SCR='GTTTTAGAGCTAGAAATAGCAAGTT'
SCR1='GTTTTAGAGCT'
FIVE='GGACGAAACACCG'
guides=[]; by={}
for l in open('/task/input/library.tsv'):
    f=l.rstrip('\n').split('\t')
    if f[0]=='sgRNA': continue
    guides.append(f[1]); by[f[1]]=f[0]
pre=collections.defaultdict(list)   # key by 19 first chars minus one pos for 1-mm lookup
for gi,g in enumerate(guides):
    for pos in range(20):
        pre[g[:pos]+g[pos+1:]+str(pos)].append(gi)

def get_spacers(s):
    out=[]
    p=s.find(FIVE)
    if p>=0 and len(s)>=p+len(FIVE)+20: out.append((s[p+len(FIVE):p+len(FIVE)+20],'five'))
    q=s.find(SCR1)
    if q>=20: out.append((s[q-20:q],'scr'))
    return out

stats={}
for path in sys.argv[1:]:
    tot=0; strict=0; loose=set(); exact=0; onemm_unique=0; onemm_amb=0; nomatch=0; mapped_idx=set()
    for i,line in enumerate(gzip.open(path,'rt')):
        if i%4!=1: continue
        s=line.rstrip('\n'); tot+=1
        cands=[]
        for orientation,seq in (('f',s),('r',rc(s))):
            sp=get_spacers(seq)
            # strict context
            if P5 in seq:
                k=seq.find(P5)
                if len(seq)>=k+len(P5)+20+8 and seq[k+len(P5)+20:k+len(P5)+47]==SCR[:27] if False else False: pass
            for x,src in sp:
                cands.append((x,src,orientation))
        ex=set(x for x,src,o in cands if x in by)
        if ex:
            exact+=1
            mapped_idx.add(by[next(iter(ex))])
            continue
        # 1-mismatch rescue
        hits=set()
        for x,src,o in cands:
            if len(x)!=20 or 'N' in x: continue
            for pos in range(20):
                for gi in pre.get(x[:pos]+x[pos+1:]+str(pos),[]):
                    hits.add(gi)
        if len(hits)==1:
            onemm_unique+=1; mapped_idx.add(guides[next(iter(hits))])
        elif len(hits)>1:
            onemm_amb+=1
        else:
            nomatch+=1
    print('%-8s tot %6d exact %6d onemm_unique %6d onemm_amb %5d nomatch %6d  distinct_guides %d'%(path.split('/')[-1],tot,exact,onemm_unique,onemm_amb,nomatch,len(mapped_idx)))
