import gzip,sys,collections
COMP=str.maketrans('ACGTN','TGCAN')
def rc(s): return s.translate(COMP)[::-1]
P5='TCTTGTGGAAAGGACGAAACACCG'
SCR='GTTTTAGAGCTAGAAATAGCAAGTT'
FIVE='GGACGAAACACCG'; SCR1='GTTTTAGAGCT'
guides=[];by={}
for l in open('/task/input/library.tsv'):
    f=l.rstrip('\n').split('\t')
    if f[0]=='sgRNA': continue
    guides.append(f[1]); by[f[1]]=len(guides)-1
delete=collections.defaultdict(list)
for s,name in ((P5,'P5'),(SCR,'SCR')):
    for i in range(len(s)):
        delete[s[:i]+s[i+1:]].append((name,i))
for path in sys.argv[1:]:
    tot=0;a=0;b_only=0;c_one=0;ctx=0;nohit=0
    for i,line in enumerate(gzip.open(path,'rt')):
        if i%4!=1: continue
        s=line.rstrip('\n'); tot+=1
        found=False
        for seq in (s,rc(s)):
            p=seq.find(FIVE); q=seq.find(SCR1)
            sp=[]
            if p>=0: sp.append(seq[p+len(FIVE):p+len(FIVE)+20])
            if q>=20: sp.append(seq[q-20:q])
            if any(x in by for x in sp): a+=1; found=True; break
        if found: continue
        # sliding window exact spacer
        hit=False
        for seq in (s,rc(s)):
            for w in range(len(seq)-19):
                if seq[w:w+20] in by:
                    hit=True; break
            if hit: break
        if hit:
            b_only+=1; continue
        # tolerant anchor + exact spacer, or tolerant anchor + 1mm spacer
        done=False
        for seq in (s,rc(s)):
            for w in range(len(seq)-22):
                k=seq[w:w+23]
                for name,pos in delete.get(k,()):
                    if name=='P5':
                        x=seq[w+24:w+44]
                        if len(x)==20 and x in by: done=True
            if done: break
        if done: ctx+=1; continue
        nohit+=1
    print('%-10s tot %6d exactanchor %6d (%.1f%%) windowonly %5d toleranchor %5d none %6d'%(path.split('/')[-1],tot,a,100*a/tot,b_only,ctx,nohit))
