#!/usr/bin/env python3
"""Final sgRNA counting for VAL-2: exact library spacer in amplicon context, both orientations."""
import gzip, sys, os, json
COMP=str.maketrans('ACGTN','TGCAN')
def rc(s): return s.translate(COMP)[::-1]
FIVE='GGACGAAACACCG'   # 3' end of the 5' amplicon constant, spacer follows
SCR='GTTTTAGAGCT'      # 5' end of the scaffold, spacer precedes

def main():
    lib,sheet,outdir=sys.argv[1],sys.argv[2],sys.argv[3]
    ids=[];seqs=[];genes=[];by={}
    for l in open(lib):
        f=l.rstrip('\n').split('\t')
        if f[0]=='sgRNA': continue
        ids.append(f[0]); seqs.append(f[1]); genes.append(f[2]); by[f[1]]=len(ids)-1
    rows=[l.rstrip('\n').split('\t') for l in open(sheet)][1:]
    samples=[r[0] for r in rows]
    fastqs=[os.path.join(os.path.dirname(sheet),'fastq',r[3]) for r in rows]
    counts=[[0]*len(samples) for _ in ids]
    qc={}
    arm_in={r[0]:r[1] for r in rows}
    for j,path in enumerate(fastqs):
        tot=0; mapped=0; amb=0
        with gzip.open(path,'rt') as fh:
            for i,line in enumerate(fh):
                if i%4!=1: continue
                s=line.rstrip('\n'); tot+=1
                hits=set()
                for seq in (s, rc(s)):
                    p=seq.find(FIVE)
                    if p>=0:
                        x=seq[p+len(FIVE):p+len(FIVE)+20]
                        if x in by: hits.add(by[x])
                    q=seq.find(SCR)
                    if q>=20:
                        x=seq[q-20:q]
                        if x in by: hits.add(by[x])
                if not hits:  # tolerate sequencing errors in the constant regions
                    for seq in (s, rc(s)):
                        for w in range(len(seq)-19):
                            x=seq[w:w+20]
                            if x in by: hits.add(by[x])
                if len(hits)==1:
                    counts[next(iter(hits))][j]+=1; mapped+=1
                elif len(hits)>1:
                    amb+=1
        qc[samples[j]]={'total_reads':tot,'mapped_reads':mapped,'ambiguous':amb,'sheet_arm':arm_in[samples[j]],'fastq':os.path.basename(path)}
        print(samples[j],qc[samples[j]],flush=True)
    os.makedirs(outdir,exist_ok=True)
    with open(os.path.join(outdir,'counts.tsv'),'w') as o:
        o.write('sgRNA\tgene\t'+'\t'.join(samples)+'\n')
        for gid,g,row in zip(ids,genes,counts):
            o.write(gid+'\t'+g+'\t'+'\t'.join(map(str,row))+'\n')
    json.dump(qc,open(os.path.join(outdir,'count_qc.json'),'w'),indent=1)
main()
EOF
